post_install:
$userData = Join-Path $env:LOCALAPPDATA 'UniGetUI'
$sources = @((Join-Path $dir 'Settings'))
if ($env:SCOOP) {
    $sources += (Join-Path $env:SCOOP 'apps\unigetui\current\Settings')
    $sources += (Join-Path $env:SCOOP 'apps\unigetui-portable\current\Settings')
    $sources += (Join-Path $env:SCOOP 'persist\unigetui-portable\Settings')
}
foreach ($source in ($sources | Select-Object -Unique)) {
    if (Test-Path -LiteralPath $source -PathType Container) {
        $items = @(Get-ChildItem -LiteralPath $source -Force -ErrorAction SilentlyContinue)
        if ($items.Count -gt 0) {
            New-Item -ItemType Directory -Path $userData -Force | Out-Null
            foreach ($item in $items) {
                $target = Join-Path $userData $item.Name
                if (-not (Test-Path -LiteralPath $target)) {
                    try {
                        Copy-Item -LiteralPath $item.FullName -Destination $target -Recurse -Force -ErrorAction Stop
                    } catch {
                        Write-Warning "Could not migrate '$($item.FullName)' to '$target': $_"
                    }
                }
            }
        }
    }
}
$portableMarker = Join-Path $dir 'ForceUniGetUIPortable'
if (Test-Path -LiteralPath $portableMarker) {
    Remove-Item -LiteralPath $portableMarker -Force
}
